            <div class="product-grid">
                @foreach (var product in _result.Items)
                {
                    <div class="product-card" @onclick="() => OnProductSelected.InvokeAsync(product.Id)" tabindex="0">
                        <div class="product-image" role="img" aria-label="@product.Name">
                            @product.Name
                        </div>
                        <div class="product-info">
