                    <button class="btn btn-page @(page == _currentPage ? "active" : "")"
                            @onclick="() => GoToPage(page)">
                        @page
                    </button>
                }

                <button class="btn btn-page"
                        disabled="@(_currentPage >= TotalPages)"
                        @onclick="() => GoToPage(_currentPage + 1)">
                    Next
                </button>
            </nav>
        }
    </main>
