+                <div class="spinner"></div>
+                <p>Loading products…</p>
+            </div>
+        }
+        else if (_result is null || _result.Items.Count == 0)
+        {
+            <div class="empty-state">
+                <p>No products found matching your criteria.</p>
+                <button class="btn btn-secondary" @onclick="ClearFilters">Clear Filters</button>
+            </div>
+        }
+        else
+        {
+            <!-- Toolbar -->
+            <div class="catalog-toolbar">
+                <div class="sort-control">
+                    <label for="sort-select">Sort by:</label>
+                    <select id="sort-select" @bind="_sortBy" @bind:after="OnSortChanged">
+                        <option value="price_asc">Price: Low to High</option>
+                        <option value="price_desc">Price: High to Low</option>
+                        <option value="name_asc">Name: A-Z</option>
+                        <option value="rating_desc">Rating: Highest</option>
+                    </select>
+                </div>
+                <span class="results-info">
+                    Showing @((_result.Page - 1) * _result.PageSize + 1)–@(Math.Min(_result.Page * _result.PageSize, _result.TotalCount)) of @_result.TotalCount products
+                </span>
+            </div>
+
+            <!-- Product Grid -->
+            <div class="product-grid">
+                @foreach (var product in _result.Items)
+                {
+                    <div class="product-card" @onclick="() => OnProductSelected.InvokeAsync(product.Id)" tabindex="0">
+                        <div class="product-image" role="img" aria-label="@product.Name">
+                            @product.Name
+                        </div>
+                        <div class="product-info">
+                            <h4 class="product-name">@product.Name</h4>
+                            <p class="product-price">@product.Price.ToString("C")</p>
+                            <div class="product-rating" title="@($"{product.Rating:F1} out of 5")">
+                                @GetStarRating(product.Rating)
+                            </div>
+                            @if (!product.InStock)
+                            {
+                                <span class="badge out-of-stock">Out of Stock</span>
+                            }
+                            <button class="btn btn-cart"
+                                    disabled="@(!product.InStock)"
+                                    @onclick="() => { }"
+                                    @onclick:stopPropagation="true">
+                                Add to Cart
+                            </button>
+                        </div>
+                    </div>
+                }
+            </div>
+
+            <!-- Pagination -->
+            <nav class="pagination" aria-label="Product page navigation">
+                <button class="btn btn-page"
+                        disabled="@(_currentPage <= 1)"
+                        @onclick="() => GoToPage(_currentPage - 1)">
+                    Previous
+                </button>
+
+                @for (int i = 1; i <= TotalPages; i++)
+                {
+                    var page = i;
+                    <button class="btn btn-page @(page == _currentPage ? "active" : "")"
+                            @onclick="() => GoToPage(page)">
+                        @page
+                    </button>
+                }
+
+                <button class="btn btn-page"
+                        disabled="@(_currentPage >= TotalPages)"
+                        @onclick="() => GoToPage(_currentPage + 1)">
+                    Next
+                </button>
+            </nav>
+        }
+    </main>
+</div>
+
+@code {
+    [Parameter]
+    public EventCallback<int> OnProductSelected { get; set; }
+
+    private List<string>? _categories;
+    private HashSet<string> _selectedCategories = new();
+    private decimal? _minPrice;
+    private decimal? _maxPrice;
+    private bool _inStockOnly;
+    private string _sortBy = "price_asc";
+    private int _currentPage = 1;
+    private const int PageSize = 12;
+
+    private PagedResult<Product>? _result;
+    private bool _loading = true;
+    private string? _error;
+
+    private int TotalPages => _result is null || _result.TotalCount == 0
+        ? 1
+        : (int)Math.Ceiling((double)_result.TotalCount / _result.PageSize);
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadInitialDataAsync();
+    }
+
+    private async Task LoadInitialDataAsync()
+    {
+        _loading = true;
+        _error = null;
+
+        try
+        {
+            var categoriesTask = ProductService.GetCategoriesAsync();
+            var productsTask = SearchProductsAsync();
+
+            _categories = await categoriesTask;
+            await productsTask;
+        }
+        catch (Exception ex)
+        {
+            _error = $"Failed to load catalog: {ex.Message}";
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private async Task SearchProductsAsync()
+    {
+        _loading = true;
+        _error = null;
+
+        try
+        {
+            var filter = new ProductFilter(
+                Categories: _selectedCategories.Count > 0 ? _selectedCategories.ToList() : null,
+                MinPrice: _minPrice,
+                MaxPrice: _maxPrice,
+                InStockOnly: _inStockOnly
+            );
+
+            _result = await ProductService.SearchAsync(filter, _sortBy, _currentPage, PageSize);
+        }
+        catch (Exception ex)
+        {
+            _error = $"Failed to load products: {ex.Message}";
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private void ToggleCategory(string category, bool isChecked)
+    {
+        if (isChecked)
+            _selectedCategories.Add(category);
+        else
+            _selectedCategories.Remove(category);
+    }
+
+    private async Task ApplyFilters()
+    {
+        _currentPage = 1;
+        await SearchProductsAsync();
+    }
+
+    private async Task ClearFilters()
+    {
+        _selectedCategories.Clear();
+        _minPrice = null;
+        _maxPrice = null;
+        _inStockOnly = false;
+        _currentPage = 1;
+        await SearchProductsAsync();
+    }
+
+    private async Task OnSortChanged()
+    {
+        _currentPage = 1;
+        await SearchProductsAsync();
+    }
+
+    private async Task GoToPage(int page)
+    {
+        if (page < 1 || page > TotalPages) return;
+        _currentPage = page;
+        await SearchProductsAsync();
+    }
+
+    private async Task RetryLoad()
+    {
+        await LoadInitialDataAsync();
+    }
+
+    private static string GetStarRating(double rating)
+    {
+        int fullStars = (int)Math.Round(rating);
+        int emptyStars = 5 - fullStars;
+        return new string('★', fullStars) + new string('☆', emptyStars);
+    }
+}
